// Module: sva_basic_sva
//
// SystemVerilog Assertions (SVA) checker module. Drop in beside
// `sva_basic_regs` via the companion bind snippet
// (`sva_basic_sva_bind.svh`). Each category is opt-in
// via device-level `sv-assert-*` flags; only enabled categories appear here.
//
// Enabled in this build:
//   * reset           — storage equals reset value while `!rst_n`
//   * decode_mutex    — at most one wr_hit_/rd_hit_ asserts per cycle
//   * w1c             — `on-write: clear` fields clear written bits next cycle
//   * ro_invariance   — fully-RO fields (SW RO + HW RO) hold reset value
// =============================================================================
module sva_basic_sva
  import sva_basic_pkg::*;
(
  input  logic                          clk,
  input  logic                          rst_n,
  input  logic [CPUIF_DATA_W-1:0]       cpuif_wr_data,
  input  logic [CPUIF_DATA_W-1:0]       cpuif_wr_biten,
  input  logic                wr_hit_status,
  input  logic                rd_hit_status,
  input  logic [31:0]                storage_status,
  input  logic                wr_hit_version,
  input  logic                rd_hit_version,
  input  logic [31:0]                storage_version
);


  // ---- decode_mutex --------------------------------------------------------
  // No two hit signals may assert simultaneously. (`$onehot0` tolerates the
  // all-zero idle case.)
  property p_decode_mutex;
    @(posedge clk) disable iff (!rst_n)
      $onehot0({ wr_hit_status, rd_hit_status, wr_hit_version, rd_hit_version });
  endproperty
  a_decode_mutex: assert property (p_decode_mutex)
    else $error("decode mutex violated");



  // ---- reset ---------------------------------------------------------------
  // Storage holds its reset value during the assertion of rst_n. Per-register
  // because reset literals are per-register.

  a_reset_status: assert property (
    @(posedge clk) (!rst_n) |-> ##1 (storage_status == 32'h0));

  a_reset_version: assert property (
    @(posedge clk) (!rst_n) |-> ##1 (storage_version == 32'hcafebabe));




  // ---- w1c -----------------------------------------------------------------
  // After a write transaction that hits the register, every W1C field's bits
  // were cleared exactly where the previous-cycle wdata&biten said `1`.

  a_w1c_status_error: assert property (
    @(posedge clk) disable iff (!rst_n)
      $past(wr_hit_status) |->
        (storage_status[0] === ($past(storage_status[0]) & ~$past(cpuif_wr_data[0] & cpuif_wr_biten[0]))));

  a_w1c_status_warn: assert property (
    @(posedge clk) disable iff (!rst_n)
      $past(wr_hit_status) |->
        (storage_status[1] === ($past(storage_status[1]) & ~$past(cpuif_wr_data[1] & cpuif_wr_biten[1]))));




  // ---- ro_invariance -------------------------------------------------------
  // Fully-RO fields (SW RO + HW RO, no hw-set/hw-clr, no intr) hold their
  // reset value indefinitely after reset deasserts.

  a_ro_version_major: assert property (
    @(posedge clk) (rst_n) |-> (storage_version[31:24] == 8'hca));

  a_ro_version_minor: assert property (
    @(posedge clk) (rst_n) |-> (storage_version[23:16] == 8'hfe));

  a_ro_version_patch: assert property (
    @(posedge clk) (rst_n) |-> (storage_version[15:0] == 16'hbabe));



  // Sink any inputs that aren't referenced by an enabled category — keeps
  // verilator quiet about unused ports when only one category is on.
  wire _unused_sva;
  assign _unused_sva = ^{clk, rst_n, cpuif_wr_data, cpuif_wr_biten, wr_hit_status, rd_hit_status, storage_status, wr_hit_version, rd_hit_version, storage_version};

endmodule : sva_basic_sva

