// UVM RAL smoke sequence for `sva_basic_ral_pkg`.
//
// A minimal `uvm_sequence` that exercises every register in the model
// with a read-after-write (RAW) pattern. Intended as a starting point for
// verification teams — not run by OSS CI (Verilator lacks UVM). Drop the
// sequence onto a sequencer connected to a `uvm_reg_predictor` and the
// generated `sva_basic_reg_block` to get smoke
// coverage of the RAL model itself.
// =============================================================================
`ifndef _SVA_BASIC_RAL_SMOKE_SEQ_SV
`define _SVA_BASIC_RAL_SMOKE_SEQ_SV

package sva_basic_ral_smoke_pkg;

  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import sva_basic_ral_pkg::*;

  class sva_basic_ral_smoke_seq extends uvm_sequence;
    `uvm_object_utils(sva_basic_ral_smoke_seq)

    sva_basic_reg_block model;
    uvm_status_e status;
    uvm_reg_data_t rdata;
    uvm_reg_data_t wdata;

    function new(string name = "sva_basic_ral_smoke_seq");
      super.new(name);
    endfunction

    virtual task body();
      if (model == null) begin
        `uvm_fatal(get_type_name(), "RAL model handle not assigned before smoke seq")
      end


      // status — RW: write pattern, read back, check equality.
      wdata = 'h5aa55aa5;
      model.status.write(status, wdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("write(status) status=%s", status.name()))
      end
      model.status.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(status) status=%s", status.name()))
      end



      // version — RO: read-only smoke (no write).
      model.version.read(status, rdata);
      if (status != UVM_IS_OK) begin
        `uvm_error(get_type_name(),
                   $sformatf("read(version) status=%s", status.name()))
      end


    endtask

  endclass : sva_basic_ral_smoke_seq

endpackage : sva_basic_ral_smoke_pkg

`endif // _SVA_BASIC_RAL_SMOKE_SEQ_SV

